// Concept: key registry pattern
interface KeyPair {
 kid: string;
 privateKey: string;
 publicKey: string;
 active: boolean;
}

const KEY_REGISTRY: KeyPair[] = []; // populated from env or key store

function verifyAccessToken(token: string): JwtPayload {
 const decoded = jwt.decode(token, { complete: true });
 const kid = decoded?.header?.kid ?? 'nova-default';
 const key = KEY_REGISTRY.find(k => k.kid === kid) ?? KEY_REGISTRY.find(k => k.active);
 if (!key) throw new Error('No matching key found');
 return jwt.verify(token, key.publicKey, { algorithms: ['RS256'] }) as JwtPayload;
}

